contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount <= address(c).balance);

        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool sendSucceeded;
        c.sendMoney(payable(address(this)), amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            sendSucceeded = false;
        } else {
            sendSucceeded = true;
        }

        assert((sendSucceeded && address(c).balance == beforeBalance - amount && c.depositsCount() == beforeDeposits) || (!sendSucceeded && address(c).balance == beforeBalance && c.depositsCount() == beforeDeposits));
    }

    receive() external payable {}
}

