// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(amount <= address(c).balance);
        uint beforeBalance = address(c).balance;
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        bool sendSucceeded;
        try c.sendMoney(payable(address(this)), amount) {
            sendSucceeded = true;
        } catch {
            sendSucceeded = false;
        }
        assertTrue((sendSucceeded && address(c).balance == beforeBalance - amount && c.depositsCount() == beforeDeposits) || (!sendSucceeded && address(c).balance == beforeBalance && c.depositsCount() == beforeDeposits));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
